INSERT IGNORE INTO provider_callback_inbox(
  channel_id, event_key, event_type, attempt_id, payload_digest, payload_size, outcome
) VALUES (
  #{channelId}, #{eventKey}, #{eventType}, #{attemptId}, #{payloadDigest},
  #{payloadSize}, #{outcome}
)

mapper.select:
SELECT * FROM provider_callback_inbox
WHERE channel_id = #{channelId} AND event_key = #{eventKey}
FOR UPDATE

mapper.insert:
INSERT INTO provider_callback_conflict(
  channel_id, event_key, existing_digest, incoming_digest, payload_size
) VALUES (
  #{channelId}, #{eventKey}, #{existingDigest}, #{incomingDigest}, #{payloadSize}
)
ON DUPLICATE KEY UPDATE channel_id = channel_id
